      "data": {
        "IT": {
          "prayer_offerings": {
            "text": "Con queste offerte\naccogli, o Signore, le preghiere del tuo popolo,\nperché i sacramenti, scaturiti dal mistero pasquale,\nper tua grazia ci ottengano la salvezza eterna.\nPer Cristo nostro Signore.",
            "lines": [
              {
                "sp": "",
                "text": "Con queste offerte"
              },
              {
                "sp": "",
                "text": "accogli, o Signore, le preghiere del tuo popolo,"
              },
              {
                "sp": "",
                "text": "perché i sacramenti, scaturiti dal mistero pasquale,"
              },
              {
                "sp": "",
                "text": "per tua grazia ci ottengano la salvezza eterna."
              },
              {
                "sp": "",
                "text": "Per Cristo nostro Signore."
              }
            ]
          },
          "communion": {
            "text": "Cristo, nostra Pasqua, è stato immolato! Alleluia.\nCelebriamo dunque la festa\ncon azzimi di sincerità e di verità.\nAlleluia, alleluia.",
            "lines": [
              {
                "sp": "",
                "text": "Cristo, nostra Pasqua, è stato immolato! Alleluia."
              },
              {
                "sp": "",
                "text": "Celebriamo dunque la festa"
              },
              {
                "sp": "",
                "text": "con azzimi di sincerità e di verità."
              },
              {
                "sp": "",
                "text": "Alleluia, alleluia."
              }
            ]
          },
          "prayer_after": {
            "text": "Infondi in noi, o Signore,\nlo Spirito della tua carità,\nperché saziati dai sacramenti pasquali\nviviamo concordi nel tuo amore.\nPer Cristo nostro Signore.",
            "lines": [
              {
                "sp": "",
                "text": "Infondi in noi, o Signore,"
              },
              {
                "sp": "",
                "text": "lo Spirito della tua carità,"
              },
              {
                "sp": "",
                "text": "perché saziati dai sacramenti pasquali"
              },
              {
                "sp": "",
                "text": "viviamo concordi nel tuo amore."
              },
              {
                "sp": "",
                "text": "Per Cristo nostro Signore."
              }
            ]
          },
          "collect": {
            "text": "O Dio,che illumini questa santissima notte\ncon la gloria della risurrezione del Signore,\nravviva nella tua Chiesa lo spirito di adozione filiale,\nperché, rinnovati nel corpo e nell’anima,\nsiamo sempre fedeli al tuo servizio.\nPer il nostro Signore Gesù Cristo, tuo Figlio, che è Dio,\ne vive e regna con te, nell’unità dello Spirito Santo,\nper tutti i secoli dei secoli.",
            "lines": [
              {
                "sp": "",
                "text": "O Dio,che illumini questa santissima notte"
              },
              {
                "sp": "",
                "text": "con la gloria della risurrezione del Signore,"
              },
              {
                "sp": "",
                "text": "ravviva nella tua Chiesa lo spirito di adozione filiale,"
              },
              {
                "sp": "",
                "text": "perché, rinnovati nel corpo e nell’anima,"
              },
              {
                "sp": "",
                "text": "siamo sempre fedeli al tuo servizio."
              },
              {
                "sp": "",
                "text": "Per il nostro Signore Gesù Cristo, tuo Figlio, che è Dio,"
              },
              {
                "sp": "",
                "text": "e vive e regna con te, nell’unità dello Spirito Santo,"
              },
              {
                "sp": "",
                "text": "per tutti i secoli dei secoli."
              }
            ]
          }
        }
      },
